Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'CARATEDOENNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &CarAteDoenNome1.FromString(&GridStateDynamicFilter.Value) If not &CarAteDoenNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterCarAteDoenNomeDescription = format('%1 (%2)', "da Doença", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterCarAteDoenNomeDescription = format('%1 (%2)', "da Doença", "WWP_FilterContains") EndCase &CarAteDoenNome = &CarAteDoenNome1 print printBlockFilterCarAteDoenNome EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'CARATEDOENNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &CarAteDoenNome2.FromString(&GridStateDynamicFilter.Value) If not &CarAteDoenNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterCarAteDoenNomeDescription = format('%1 (%2)', "da Doença", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterCarAteDoenNomeDescription = format('%1 (%2)', "da Doença", "WWP_FilterContains") EndCase &CarAteDoenNome = &CarAteDoenNome2 print printBlockFilterCarAteDoenNome EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'CARATEDOENNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &CarAteDoenNome3.FromString(&GridStateDynamicFilter.Value) If not &CarAteDoenNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterCarAteDoenNomeDescription = format('%1 (%2)', "da Doença", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterCarAteDoenNomeDescription = format('%1 (%2)', "da Doença", "WWP_FilterContains") EndCase &CarAteDoenNome = &CarAteDoenNome3 print printBlockFilterCarAteDoenNome EndIf EndCase EndIf EndIf EndIf If not (&TFAreEnsCodigo.IsEmpty() AND &TFAreEnsCodigo_To.IsEmpty()) print printBlockTFAreEnsCodigo &TFAreEnsCodigo_To_Description = format('%1 (%2)', "Área Ensino", "WWP_TSTo") print printBlockTFAreEnsCodigo_To EndIf If not (&TFAreEnsSequencial.IsEmpty() AND &TFAreEnsSequencial_To.IsEmpty()) print printBlockTFAreEnsSequencial &TFAreEnsSequencial_To_Description = format('%1 (%2)', "Etapa", "WWP_TSTo") print printBlockTFAreEnsSequencial_To EndIf &TFcarTurno_Sels.FromJson(&TFcarTurno_SelsJson) If not &TFcarTurno_Sels.Count = 0 &i = 1 For &TFcarTurno_Sel in &TFcarTurno_Sels If &i = 1 &TFcarTurno_SelDscs = '' Else &TFcarTurno_SelDscs += ', ' EndIf &FilterTFcarTurno_SelValueDescription = &TFcarTurno_Sel.EnumerationDescription()
&TFcarTurno_SelDscs += &FilterTFcarTurno_SelValueDescription &i += 1 EndFor print printBlockTFcarTurno_Sel EndIf If not (&TFcarEstNormal.IsEmpty() AND &TFcarEstNormal_To.IsEmpty()) print printBlockTFcarEstNormal &TFcarEstNormal_To_Description = format('%1 (%2)', "Normal", "WWP_TSTo") print printBlockTFcarEstNormal_To EndIf If not (&TFcarEstGluten.IsEmpty() AND &TFcarEstGluten_To.IsEmpty()) print printBlockTFcarEstGluten &TFcarEstGluten_To_Description = format('%1 (%2)', "Glúten", "WWP_TSTo") print printBlockTFcarEstGluten_To EndIf If not (&TFcarEstLactose.IsEmpty() AND &TFcarEstLactose_To.IsEmpty()) print printBlockTFcarEstLactose &TFcarEstLactose_To_Description = format('%1 (%2)', "Lactose", "WWP_TSTo") print printBlockTFcarEstLactose_To EndIf If not (&TFcarEstDiabetico.IsEmpty() AND &TFcarEstDiabetico_To.IsEmpty()) print printBlockTFcarEstDiabetico &TFcarEstDiabetico_To_Description = format('%1 (%2)', "Diabético", "WWP_TSTo") print printBlockTFcarEstDiabetico_To EndIf If not (&TFcarEstColesterol.IsEmpty() AND &TFcarEstColesterol_To.IsEmpty()) print printBlockTFcarEstColesterol &TFcarEstColesterol_To_Description = format('%1 (%2)', "Colesterol", "WWP_TSTo") print printBlockTFcarEstColesterol_To EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
