EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnscardapioAreaEnsino order CarAteDoenNome when &OrderedBy = 1 order AreEnsCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (AreEnsCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order AreEnsSequencial when &OrderedBy = 3 AND &OrderedDsc = False order (AreEnsSequencial) when &OrderedBy = 3 AND &OrderedDsc = True order carTurno when &OrderedBy = 4 AND &OrderedDsc = False order (carTurno) when &OrderedBy = 4 AND &OrderedDsc = True order carEstNormal when &OrderedBy = 5 AND &OrderedDsc = False order (carEstNormal) when &OrderedBy = 5 AND &OrderedDsc = True order carEstGluten when &OrderedBy = 6 AND &OrderedDsc = False order (carEstGluten) when &OrderedBy = 6 AND &OrderedDsc = True order carEstLactose when &OrderedBy = 7 AND &OrderedDsc = False order (carEstLactose) when &OrderedBy = 7 AND &OrderedDsc = True order carEstDiabetico when &OrderedBy = 8 AND &OrderedDsc = False order (carEstDiabetico) when &OrderedBy = 8 AND &OrderedDsc = True order carEstColesterol when &OrderedBy = 9 AND &OrderedDsc = False order (carEstColesterol) when &OrderedBy = 9 AND &OrderedDsc = True
using trnscardapioAreaEnsinoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &CarAteDoenNome1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &CarAteDoenNome2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &CarAteDoenNome3, &TFAreEnsCodigo , &TFAreEnsCodigo_To, &TFAreEnsSequencial, &TFAreEnsSequencial_To, &TFcarTurno_Sels, &TFcarEstNormal, &TFcarEstNormal_To , &TFcarEstGluten, &TFcarEstGluten_To, &TFcarEstLactose, &TFcarEstLactose_To, &TFcarEstDiabetico, &TFcarEstDiabetico_To , &TFcarEstColesterol, &TFcarEstColesterol_To) Where prefCodigo = &prefCodigo If Not carTurno.IsEmpty() &carTurnoDescription = carTurno.EnumerationDescription() Else &carTurnoDescription.SetEmpty() Endif
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnscardapioAreaEnsinoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnscardapioAreaEnsinoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnscardapioAreaEnsinoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFAREENSCODIGO" &TFAreEnsCodigo.FromString(&GridStateFilterValue.Value) &TFAreEnsCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFAREENSSEQUENCIAL" &TFAreEnsSequencial.FromString(&GridStateFilterValue.Value) &TFAreEnsSequencial_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARTURNO_SEL" &TFcarTurno_SelsJson = &GridStateFilterValue.Value &TFcarTurno_Sels.FromJson(&TFcarTurno_SelsJson) Case &GridStateFilterValue.Name = !"TFCARESTNORMAL" &TFcarEstNormal.FromString(&GridStateFilterValue.Value) &TFcarEstNormal_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARESTGLUTEN" &TFcarEstGluten.FromString(&GridStateFilterValue.Value) &TFcarEstGluten_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARESTLACTOSE" &TFcarEstLactose.FromString(&GridStateFilterValue.Value) &TFcarEstLactose_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARESTDIABETICO" &TFcarEstDiabetico.FromString(&GridStateFilterValue.Value) &TFcarEstDiabetico_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARESTCOLESTEROL" &TFcarEstColesterol.FromString(&GridStateFilterValue.Value) &TFcarEstColesterol_To.FromString(&GridStateFilterValue.ValueTo) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
